CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_caseregulatorychange]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_caseregulatorychange]
	(
		[apuk_ageofcase],
		[apuk_areaofbreach],
		[apuk_areaofbreach_entitytype],
		[apuk_areaofbreach2],
		[apuk_areaofbreach2_entitytype],
		[apuk_areaofbreach2name],
		[apuk_areaofbreach3],
		[apuk_areaofbreach3_entitytype],
		[apuk_areaofbreach3name],
		[apuk_areaofbreachname],
		[apuk_areaofpractice],
		[apuk_areaofpractice_entitytype],
		[apuk_areaofpracticename],
		[apuk_caseclosuredate],
		[apuk_casegroupreference],
		[apuk_caseregulatorychangeid],
		[apuk_customerid],
		[apuk_customerid_entitytype],
		[apuk_customerididtype],
		[apuk_customeridname],
		[apuk_customeridyominame],
		[apuk_description],
		[apuk_escalationlevel],
		[apuk_name],
		[apuk_origin],
		[apuk_regardingtype],
		[apuk_regulatedfirm],
		[apuk_regulatedfirm_entitytype],
		[apuk_regulatedfirmname],
		[apuk_regulatedfirmyominame],
		[apuk_regulatedindividual],
		[apuk_regulatedindividual_entitytype],
		[apuk_regulatedindividualname],
		[apuk_regulatedindividualyominame],
		[apuk_regulatedscheme],
		[apuk_regulatedscheme_entitytype],
		[apuk_regulatedschemename],
		[apuk_regulatorycontactid],
		[apuk_regulatorycontactid_entitytype],
		[apuk_regulatorycontactidname],
		[apuk_regulatorycontactidyominame],
		[apuk_responsibleprincipal],
		[apuk_responsibleprincipal_entitytype],
		[apuk_responsibleprincipalname],
		[apuk_responsibleprincipalyominame],
		[apuk_ruleofconduct2],
		[apuk_ruleofconduct2_entitytype],
		[apuk_ruleofconduct2name],
		[apuk_showonline],
		[apuk_status],
		[apuk_subject],
		[apuk_subject_entitytype],
		[apuk_subjectname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		DATEDIFF(DAY, stg.createdon, COALESCE(stg.apuk_caseclosuredate,GETDATE())),
		--stg.[apuk_ageofcase],
		stg.[apuk_areaofbreach],
		stg.[apuk_areaofbreach_entitytype],
		stg.[apuk_areaofbreach2],
		stg.[apuk_areaofbreach2_entitytype],
		stg.[apuk_areaofbreach2name],
		stg.[apuk_areaofbreach3],
		stg.[apuk_areaofbreach3_entitytype],
		stg.[apuk_areaofbreach3name],
		stg.[apuk_areaofbreachname],
		stg.[apuk_areaofpractice],
		stg.[apuk_areaofpractice_entitytype],
		stg.[apuk_areaofpracticename],
		stg.[apuk_caseclosuredate],
		stg.[apuk_casegroupreference],
		stg.[apuk_caseregulatorychangeid],
		stg.[apuk_customerid],
		stg.[apuk_customerid_entitytype],
		stg.[apuk_customerididtype],
		stg.[apuk_customeridname],
		stg.[apuk_customeridyominame],
		stg.[apuk_description],
		stg.[apuk_escalationlevel],
		stg.[apuk_name],
		stg.[apuk_origin],
		stg.[apuk_regardingtype],
		stg.[apuk_regulatedfirm],
		stg.[apuk_regulatedfirm_entitytype],
		stg.[apuk_regulatedfirmname],
		stg.[apuk_regulatedfirmyominame],
		stg.[apuk_regulatedindividual],
		stg.[apuk_regulatedindividual_entitytype],
		stg.[apuk_regulatedindividualname],
		stg.[apuk_regulatedindividualyominame],
		stg.[apuk_regulatedscheme],
		stg.[apuk_regulatedscheme_entitytype],
		stg.[apuk_regulatedschemename],
		stg.[apuk_regulatorycontactid],
		stg.[apuk_regulatorycontactid_entitytype],
		stg.[apuk_regulatorycontactidname],
		stg.[apuk_regulatorycontactidyominame],
		stg.[apuk_responsibleprincipal],
		stg.[apuk_responsibleprincipal_entitytype],
		stg.[apuk_responsibleprincipalname],
		stg.[apuk_responsibleprincipalyominame],
		stg.[apuk_ruleofconduct2],
		stg.[apuk_ruleofconduct2_entitytype],
		stg.[apuk_ruleofconduct2name],
		stg.[apuk_showonline],
		stg.[apuk_status],
		stg.[apuk_subject],
		stg.[apuk_subject_entitytype],
		stg.[apuk_subjectname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_caseregulatorychange] stg
		LEFT JOIN [synapse_ce].[apuk_caseregulatorychange] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
